CREATE TABLE IF NOT EXISTS changes (id INTEGER PRIMARY KEY AUTOINCREMENT, entry TEXT NOT NULL, before TEXT, after TEXT, by TEXT NOT NULL DEFAULT '', what TEXT NOT NULL DEFAULT '', t INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS blocks (id INTEGER PRIMARY KEY AUTOINCREMENT, ip TEXT NOT NULL DEFAULT '', account TEXT NOT NULL DEFAULT '' COLLATE NOCASE, note TEXT NOT NULL DEFAULT '', by TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS blocks_ip ON blocks(ip);
CREATE TABLE IF NOT EXISTS subip (sub INTEGER PRIMARY KEY, ip TEXT NOT NULL);
